#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

using namespace std;

const int MAXN = 66;

int r, c, n;
string s;
long long comb[MAXN][MAXN];

int cntA[MAXN], cntB[MAXN];
vector<long long> partials[MAXN], partialsZero[MAXN];

void generate_combinations() {
    for (int i = 0; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
    }
}

long long compute_diff(int conf, int a_prev, int b_prev) {
    long long total_diff = 0;
    for (int i = 0; i <= c; ++i) {
        if (conf & (1 << i)) {
            b_prev++;
            long long aux1 = comb[b_prev - 1][r - 1];
            long long aux2 = comb[n - b_prev][r] - comb[a_prev][r];
            total_diff -= aux1 * aux2;
        } else {
            a_prev++;
            long long aux1 = comb[a_prev - 1][r - 1];
            long long aux2 = comb[n - a_prev][r] - comb[b_prev][r];
            total_diff += aux1 * aux2;
        }
    }
    return total_diff;
}

bool is_valid_conf(int conf) {
    for (int i = 0; i <= c; ++i) {
        if (s[2 * r + c + i] == 'A' && ((conf >> i) & 1) == 1) return false;
        if (s[2 * r + c + i] == 'B' && ((conf >> i) & 1) == 0) return false;
    }
    return true;
}

void process_second() {
    int total_conf = 1 << (c + 1);
    for (int conf = 0; conf < total_conf; ++conf) {
        int b_count = __builtin_popcount(conf);
        int a_count = c + 1 - b_count;
        if (is_valid_conf(conf))
            partials[a_count].push_back(compute_diff(conf, r + c - a_count, r + c - b_count));
        else
            partialsZero[a_count].push_back(compute_diff(conf, r + c - a_count, r + c - b_count));
    }
    for (int i = 0; i <= c + 1; ++i) {
        sort(partials[i].begin(), partials[i].end());
        sort(partialsZero[i].begin(), partialsZero[i].end());
    }
}

long long get_coefficient(int conf) {
    int i;
    for (i = 0; i <= c; ++i) {
        if ( ((conf >> i) & 1) != (conf & 1) ) break;
    }
    for (int j = i; j <= c; ++j) {
        if (s[2 * r - 1 + j] == 'A' && (((conf >> j) & 1) == 1)) return 0;
        if (s[2 * r - 1 + j] == 'B' && (((conf >> j) & 1) == 0)) return 0;
    }
    int setA = r - 1 + ( (conf & 1) == 0 ? i : 0 );
    int setB = r - 1 + ( (conf & 1) == 1 ? i : 0 );
    if (setA < cntA[2 * r - 2 + i]) return 0;
    if (setB < cntB[2 * r - 2 + i]) return 0;
    int total = setA + setB - cntA[2 * r - 2 + i] - cntB[2 * r - 2 + i];
    return comb[total][setA - cntA[2 * r - 2 + i]];
}

void update_result(pair<long long, long long>& answer, pair<long long, long long> current) {
    if (current.first < 0) current.first = -current.first;
    if (answer.first > current.first) {
        answer = current;
    } else if (answer.first == current.first) {
        answer.second += current.second;
    }
}

long long count_in_vector(const vector<long long>& data, long long val) {
    auto low = lower_bound(data.begin(), data.end(), val);
    auto up = upper_bound(data.begin(), data.end(), val);
    return up - low;
}

long long solve() {
    int total_conf = 1 << (c + 1);
    pair<long long, long long> answer = {1LL << 60, 0};
    for (int conf = 0; conf < total_conf; ++conf) {
        int b_count = __builtin_popcount(conf);
        int a_count = c + 1 - b_count;
        long long act = compute_diff(conf, r - 1, r - 1);
        long long coef = get_coefficient(conf);
        auto it = lower_bound(partials[c + 1 - a_count].begin(), partials[c + 1 - a_count].end(), -act);
        if (it != partials[c + 1 - a_count].end()) {
            long long val = *it + act;
            if (abs(val) <= answer.first) {
                long long count_coef = count_in_vector(partials[c + 1 - a_count], *it);
                update_result(answer, {abs(val), coef * count_coef});
            }
        }
        if (it != partials[c + 1 - a_count].begin()) {
            --it;
            long long val = *it + act;
            if (abs(val) <= answer.first) {
                long long count_coef = count_in_vector(partials[c + 1 - a_count], *it);
                update_result(answer, {abs(val), coef * count_coef});
            }
        }
        long long zero_coef = 0;
        auto it_zero = lower_bound(partialsZero[c + 1 - a_count].begin(), partialsZero[c + 1 - a_count].end(), -act);
        if (it_zero != partialsZero[c + 1 - a_count].end()) {
            long long val = *it_zero + act;
            long long count_coef = count_in_vector(partials[c + 1 - a_count], *it_zero);
            if (abs(val) <= answer.first) {
                update_result(answer, {abs(val), zero_coef * count_coef});
            }
        }
        if (it_zero != partialsZero[c + 1 - a_count].begin()) {
            --it_zero;
            long long val = *it_zero + act;
            long long count_coef = count_in_vector(partials[c + 1 - a_count], *it_zero);
            if (abs(val) <= answer.first) {
                update_result(answer, {abs(val), zero_coef * count_coef});
            }
        }
    }
    return answer.second;
}

int main() {
    cin >> r >> c >> s;
    n = 2 * (r + c);
    generate_combinations();
    for (int i = 1; i <= n; ++i) {
        cntA[i] = cntA[i - 1] + (s[i - 1] == 'A' ? 1 : 0);
        cntB[i] = cntB[i - 1] + (s[i - 1] == 'B' ? 1 : 0);
    }
    process_second();
    cout << solve() << "\n";
    return 0;
}
